function drawMonsterBody(m,c){
  if(gl3dMonster(m,c))return;
  const r=m.r,t=time*(m.kind==='titan'?2:3)+m.x*.01;
  ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(m.x+3,m.y+r*.72,r*.95,r*.42,0,0,6.28);ctx.fill();
  const g=ctx.createRadialGradient(m.x-r*.35,m.y-r*.45,r*.1,m.x,m.y,r*1.05);g.addColorStop(0,shade(c,60));g.addColorStop(.6,c);g.addColorStop(1,shade(c,-70));
  ctx.fillStyle=g;ctx.strokeStyle=shade(c,-90);ctx.lineWidth=3;
  ctx.beginPath();
  if(m.kind==='stone'||m.kind==='shard'){for(let i=0;i<7;i++){const a=i/7*6.283+.3,rr=r*(i%2?.82:1.02);ctx.lineTo(m.x+Math.cos(a)*rr,m.y+Math.sin(a)*rr)}ctx.closePath()}
  else ctx.ellipse(m.x,m.y+Math.sin(t)*1.5,r,r*.92,0,0,6.28);
  ctx.fill();ctx.stroke();
  const ex=r*.32,ey=-r*.12+Math.sin(t)*1.5,ang=Math.atan2((typeof hero!=='undefined'?hero.y:m.y)-m.y,(typeof hero!=='undefined'?hero.x:m.x)-m.x);
  for(const s of[-1,1]){ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(m.x+s*ex,m.y+ey,r*.17,r*.2,0,0,6.28);ctx.fill();ctx.fillStyle=m.kind==='titan'||m.kind==='drake'?'#ff3b4e':'#14212a';ctx.beginPath();ctx.arc(m.x+s*ex+Math.cos(ang)*r*.06,m.y+ey+Math.sin(ang)*r*.06,r*.09,0,6.28);ctx.fill()}
  if(m.kind==='titan'||m.kind==='drake'||m.kind==='herald'){ctx.fillStyle=shade(c,-40);for(const s of[-1,0,1]){ctx.beginPath();ctx.moveTo(m.x+s*r*.4-r*.12,m.y-r*.8);ctx.lineTo(m.x+s*r*.4,m.y-r*1.2);ctx.lineTo(m.x+s*r*.4+r*.12,m.y-r*.8);ctx.fill()}}
  if(m.kind==='ember'){ctx.fillStyle='#ffd36b99';ctx.beginPath();ctx.arc(m.x,m.y+r*.25,r*.3+Math.sin(t*2)*2,0,6.28);ctx.fill()}
}
function drawMinionCharacter(m) {
    const cls = m.siege ? 'siege' : m.super ? 'super' : m.r >= 15 ? 'caster' : 'soldier';
    drawCharacter(m, cls, { r: m.r + (cls === 'soldier' ? 3 : 4), team: m.team, color: m.team === 'blue' ? '#3fb7e0' : '#d6475c', accent: m.team === 'blue' ? '#bff3ff' : '#ffc3cb', skin: '#d8b58f', hair: '#3a2c22' });
}

function drawJungleCampMarkers(){if(gameMode==='training')return;for(const c of jungleCamps){const m=monsters.find(x=>x.kind===c.monsterKind);if(!m||m.dead)continue;const contested=c.contest===2,color=contested?'#ffd45d':c.owner==='blue'?'#58ddff':c.owner==='red'?'#ff6678':'#8aa39c';ctx.save();ctx.globalAlpha=contested?.72:.28;ctx.strokeStyle=color;ctx.lineWidth=contested?4:2;ctx.setLineDash(contested?[9,6]:[5,9]);ctx.beginPath();ctx.arc(c.x,c.y,c.leash||180,0,6.28);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;ctx.font='800 9px system-ui';ctx.textAlign='center';ctx.fillText(c.label,c.x,c.y-(c.leash||180)-8);ctx.restore()}}
