function compactWorldHud(){return compactWorldHud.value??=(matchMedia('(pointer:coarse)').matches||innerWidth<=700)}
function drawStatusChips(u){if(!u||u.dead)return;const statuses=[];if((u.stun||0)>0)statuses.push(['STUN',u.stun,'#ffe36e']);if((u.slow||0)>0)statuses.push(['SLOW',u.slow,'#7ddcff']);if((u.poison||0)>0)statuses.push(['DOT',u.poison,'#b8f06d']);if(!statuses.length)return;const compact=compactWorldHud(),baseY=u.y-(u.r||24)-18;ctx.save();ctx.textAlign='center';ctx.font='900 7px system-ui';statuses.slice(0,2).forEach((st,i)=>{const label=st[0]+' '+Math.max(0,st[1]).toFixed(1),w=Math.max(34,ctx.measureText(label).width+12),x=u.x+(i-(Math.min(statuses.length,2)-1)/2)*(w+4),y=baseY-i*0;ctx.fillStyle='#0e303cae';ctx.strokeStyle=st[2];ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(x-w/2,y-8,w,14,7);ctx.fill();ctx.stroke();ctx.fillStyle=st[2];ctx.fillText(label,x,y+2)});ctx.restore()}

function drawBotHeroes(){if(gameMode==='training')return;for(const b of botHeroes){if(b.dead||(b.team==='red'&&(!visibleToBlue(b.x,b.y)||!brushRevealed(b))))continue;ctx.save();ctx.translate(b.x,b.y);drawCharacter(b,ROLE_CLASS[b.role]||'tank',{r:b.r,team:b.team,color:b.color,accent:b.team==='blue'?'#9cefff':'#ffb0ba',hair:shade(b.color,-.5),skin:b.team==='blue'?'#e6c3a1':'#d9ab94'});ctx.restore();if(b.stun>0||b.slow>0){ctx.strokeStyle=b.stun>0?'#ffe36e':'#7ddcff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(b.x,b.y,b.r+7,0,6.28);ctx.stroke()}drawStatusChips(b);if(b.awakening>0){ctx.strokeStyle=b.team==='blue'?'#fff1a0':'#ff7085';ctx.lineWidth=5;ctx.globalAlpha=.55+.3*Math.sin(time*12);ctx.beginPath();ctx.arc(b.x,b.y,b.r+13,0,6.28);ctx.stroke();ctx.globalAlpha=1}if((b.orderAck||0)>0){ctx.fillStyle='#8ff2bc';ctx.font='900 12px system-ui';ctx.textAlign='center';ctx.fillText('✓',b.x+25,b.y-30)}bar(b.x,b.y-38,68,7,b.hp/b.maxHp,b.team==='blue'?'#52df95':'#ff596b');const detail=!compactWorldHud()||b.team==='red'||hero.target===b||(b.orderAck||0)>0||gamepadMode==='coop'&&coopBot()===b;if(detail){ctx.fillStyle='#fff';ctx.font='700 9px system-ui';ctx.textAlign='center';ctx.fillText(b.symbol+' '+b.name,b.x,b.y-44)}if(G3.persp?hero.target===b:(!compactWorldHud()||hero.target===b)){ctx.fillStyle='#9db5bc';ctx.font='8px system-ui';ctx.fillText(b.role+(b.gear.length?' · ◈'+b.gear.length:'')+(b.level>=6&&b.ultCd<=0?' · R ГОТОВ':''),b.x,b.y+35)}}}
function drawCoopMarker(){if(gamepadMode!=='coop')return;const b=coopBot();if(!b||b.dead)return;ctx.save();ctx.strokeStyle='#fff19a';ctx.lineWidth=4;ctx.globalAlpha=.65+.25*Math.sin(time*8);ctx.beginPath();ctx.arc(b.x,b.y,(b.r||20)+11,0,6.28);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#fff19a';ctx.font='900 10px system-ui';ctx.textAlign='center';ctx.fillText('ИГРОК 2',b.x,b.y-42);ctx.restore()}
function drawEnemy(){if(gameMode==='training'||enemy.dead||!visibleToBlue(enemy.x,enemy.y)||!brushRevealed(enemy))return;ctx.save();ctx.translate(enemy.x,enemy.y);if(rivalry.level>0){ctx.strokeStyle=['','#ffb45d','#ff667d','#e69cff'][rivalry.level];ctx.lineWidth=3+rivalry.level;ctx.globalAlpha=.65+.2*Math.sin(time*6);ctx.beginPath();ctx.arc(0,0,enemy.r+9+rivalry.level*3,0,6.28);ctx.stroke();ctx.globalAlpha=1}drawCharacter(enemy,ARCH_CLASS[enemy.archetype]||'assassin',{r:enemy.r,team:'red',color:enemy.color,accent:enemy.archetype==='arcanist'?'#f0b5ff':enemy.archetype==='hunter'?'#ffe08c':'#ffb45d',hair:'#2a1a1f',skin:'#d9b09a'});ctx.restore();if(enemy.stun>0||enemy.slow>0){ctx.strokeStyle=enemy.stun>0?'#ffe36e':'#7ddcff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(enemy.x,enemy.y,enemy.r+8,0,6.28);ctx.stroke()}drawStatusChips(enemy);if(enemy.awakening>0){ctx.strokeStyle='#ff7085';ctx.lineWidth=6;ctx.globalAlpha=.6+.3*Math.sin(time*13);ctx.beginPath();ctx.arc(enemy.x,enemy.y,enemy.r+15,0,6.28);ctx.stroke();ctx.globalAlpha=1}bar(enemy.x,enemy.y-45,compactWorldHud()?72:85,9,enemy.hp/enemy.maxHp,'#ff5269');if(!compactWorldHud()||hero.target===enemy){ctx.fillStyle='#fff';ctx.font='700 11px system-ui';ctx.textAlign='center';ctx.fillText('РАЗОРИТЕЛЬ',enemy.x,enemy.y-52)}if(!compactWorldHud()||hero.target===enemy){ctx.fillStyle='#ff9aa7';ctx.font='9px system-ui';ctx.fillText(enemy.state,enemy.x,enemy.y+44)}}
function drawNexuses(){for(const n of nexuses){if(n.hp<=0)continue;const c=n.team==='blue'?'#55dcff':'#ff5269';gl3dNexus(n,c);ctx.strokeStyle=c;ctx.lineWidth=8;ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(n.x,n.y,52+Math.sin(time*3)*4,0,6.28);ctx.stroke();ctx.globalAlpha=1;bar(n.x,n.y-78,110,10,n.hp/n.maxHp,c);if(structureProtected(n)||backdoorProtected(n,n.team==='red'?'blue':'red')){ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(n.x,n.y,72+Math.sin(time*4)*3,0,6.28);ctx.stroke();ctx.globalAlpha=1}}}
function drawAccessibilityOutlines(){if(!options.highContrast)return;ctx.save();ctx.lineWidth=4;for(const u of [hero,enemy,...botHeroes]){if(u.dead||u.hp<=0||(u.team==='red'&&!visibleToBlue(u.x,u.y)))continue;ctx.strokeStyle=u.team==='blue'?'#00e5ff':'#ffb000';ctx.beginPath();if(u.team==='blue')ctx.arc(u.x,u.y,(u.r||22)+6,0,6.28);else{const r=(u.r||22)+7;ctx.rect(u.x-r,u.y-r,r*2,r*2)}ctx.stroke()}ctx.restore()}
